CalculateField Catastro\UA\Casas\CONSTRU_UA_v2.1 BT classify_construction(!CONSTRY!) PYTHON_9.3 "def classify_construction(field_value):
 if field_value is None or field_value == "":
 return 0

 # Mapeo de números romanos a valores enteros para comparación
 roman_map = {
 "I": 1, "II": 2, "III": 3, "IV": 4, "V": 5, 
 "VI": 6, "VII": 7, "VIII": 8, "IX": 9, "X": 10,
 "XI": 11, "XII": 12, "XIII": 13, "XIV": 14, "XV": 15, 
 "XVI": 16, "XVII": 17, "XVIII": 18, "XIX": 19, "XX": 20
 }

 parts = [p.strip() for p in str(field_value).split("+")]

 pos_values = []
 has_negative = False

 for p in parts:
 if p.startswith("-"):
 # Comprobamos si lo que sigue al guion es un romano válido hasta X
 if p[1:] in ["I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X"]:
 has_negative = True
 elif p in roman_map:
 pos_values.append(roman_map[p])

 if not pos_values:
 return 0

 max_pos = max(pos_values)

 # Aplicación de la lógica de clasificación:
 # Nota: El usuario distingue entre "any" y "some" negative value. 
 # En lógica booleana, si 'has_negative' es True, se cumplen ambos. 
 # He priorizado los códigos pares para "some" y impares para "any" según el orden de la solicitud.

 if max_pos == 1:
 return -2 if has_negative else 0 # Si solo hay I y negativo -> -2 (incluye -1)
 elif max_pos == 2:
 return -4 if has_negative else 0 # Si solo hay II y negativo -> -4 (incluye -3)
 elif max_pos >= 3:
 return -6 if has_negative else 0 # Si hay III o más y negativo -> -6 (incluye -5)

 return 0"

